import { getInstalledVersionInfo } from '@/services/updates/versionInfoService';
import { clearCachedLicenseToken, getOrCreateLicenseDeviceId, readCachedLicenseToken, readLicenseEndpoint, writeCachedLicenseToken, } from './tokenCacheService';
const ACTIVE_LICENSE_STATUSES = ['ACTIVE_TRIAL', 'ACTIVE', 'ACTIVE_PAID'];
const PROACTIVE_REFRESH_WINDOW_MS = 24 * 60 * 60 * 1000;
class LicenseEndpointError extends Error {
    constructor(status, message, isUnavailable = false) {
        super(message);
        this.name = 'LicenseEndpointError';
        this.status = status;
        this.isUnavailable = isUnavailable;
    }
}
const isIsoDate = (value) => !Number.isNaN(Date.parse(value));
const isRecord = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);
const isLicenseTokenShape = (value) => {
    if (!isRecord(value)) {
        return false;
    }
    if (typeof value.tokenId !== 'string' ||
        typeof value.email !== 'string' ||
        !ACTIVE_LICENSE_STATUSES.concat('INACTIVE').includes(value.status) ||
        typeof value.issuedAt !== 'string' ||
        typeof value.expiresAt !== 'string' ||
        typeof value.graceUntil !== 'string') {
        return false;
    }
    if (!isIsoDate(value.issuedAt) || !isIsoDate(value.expiresAt) || !isIsoDate(value.graceUntil)) {
        return false;
    }
    if ('refreshToken' in value && typeof value.refreshToken !== 'string') {
        return false;
    }
    return true;
};
const parseTokenFromResponse = (value) => {
    if (!isRecord(value)) {
        return null;
    }
    const tokenCandidate = value.token;
    if (!isLicenseTokenShape(tokenCandidate)) {
        return null;
    }
    return tokenCandidate;
};
const isTokenActive = (token, now) => ACTIVE_LICENSE_STATUSES.includes(token.status) && Date.parse(token.expiresAt) > now.getTime();
const isWithinGraceWindow = (token, now) => ACTIVE_LICENSE_STATUSES.includes(token.status) && Date.parse(token.graceUntil) > now.getTime();
const shouldRefreshToken = (token, now) => Date.parse(token.expiresAt) - now.getTime() <= PROACTIVE_REFRESH_WINDOW_MS;
const detectLicensePlatform = () => {
    const officeContext = Office.context;
    const rawPlatform = `${officeContext.platform || officeContext.diagnostics?.platform || ''}`
        .toLowerCase()
        .trim();
    if (rawPlatform.includes('mac')) {
        return 'excel-mac';
    }
    if (rawPlatform.includes('online') || rawPlatform.includes('web')) {
        return 'excel-online';
    }
    return 'excel-desktop';
};
const getEndpoint = () => {
    const installed = getInstalledVersionInfo();
    const fixedEndpoint = installed.licenseApiBaseUrl.trim();
    if (!installed.isDevelopmentBuild && fixedEndpoint) {
        return fixedEndpoint.replace(/\/$/, '');
    }
    const override = readLicenseEndpoint();
    return (override || fixedEndpoint).trim().replace(/\/$/, '');
};
const parseErrorMessage = async (response) => {
    try {
        const payload = (await response.json());
        if (isRecord(payload) && typeof payload.error === 'string' && payload.error.trim()) {
            return payload.error.trim();
        }
    }
    catch (_error) {
        // Fall through to status text.
    }
    if (response.status === 429) {
        return 'Too many activation attempts. Please try again shortly.';
    }
    return response.statusText || 'License service request failed.';
};
const throwForNonOkResponse = async (response) => {
    if (response.ok) {
        return;
    }
    const message = await parseErrorMessage(response);
    const isUnavailable = response.status === 429 || response.status >= 500;
    throw new LicenseEndpointError(response.status, message, isUnavailable);
};
const requestActivationFromEndpoint = async (endpoint, email, activationCode, deviceId) => {
    let response;
    try {
        response = await fetch(`${endpoint}/license-activate`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                email,
                activationCode,
                platform: detectLicensePlatform(),
                deviceId,
            }),
            cache: 'no-store',
        });
    }
    catch (_error) {
        throw new LicenseEndpointError(0, 'Unable to reach the license service. Check your connection and try again.', true);
    }
    await throwForNonOkResponse(response);
    const payload = await response.json();
    const token = parseTokenFromResponse(payload);
    if (!token) {
        throw new LicenseEndpointError(500, 'License service returned an invalid activation payload.', true);
    }
    return token;
};
const requestRefreshFromEndpoint = async (endpoint, token, deviceId) => {
    let response;
    try {
        response = await fetch(`${endpoint}/license-refresh`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({
                tokenId: token.tokenId,
                refreshToken: token.refreshToken || null,
                deviceId,
            }),
            cache: 'no-store',
        });
    }
    catch (_error) {
        throw new LicenseEndpointError(0, 'Unable to reach the license service. Check your connection and try again.', true);
    }
    await throwForNonOkResponse(response);
    const payload = await response.json();
    const refreshed = parseTokenFromResponse(payload);
    if (!refreshed) {
        throw new LicenseEndpointError(500, 'License service returned an invalid refresh payload.', true);
    }
    return refreshed;
};
const buildActiveReason = (status, refreshed = false) => {
    if (refreshed) {
        return 'License refreshed successfully.';
    }
    if (status === 'ACTIVE_TRIAL') {
        return 'Beta access is active.';
    }
    return 'License is active.';
};
const buildInactiveResult = (reason) => ({
    status: 'INACTIVE',
    isActive: false,
    reason,
    token: null,
});
export const activateLicense = async (email, activationCode) => {
    const trimmedEmail = email.trim().toLowerCase();
    const trimmedCode = activationCode.trim();
    if (!trimmedEmail || !trimmedCode) {
        return buildInactiveResult('Email and activation code are required.');
    }
    const endpoint = getEndpoint();
    if (!endpoint) {
        return buildInactiveResult('License service is not configured.');
    }
    try {
        const token = await requestActivationFromEndpoint(endpoint, trimmedEmail, trimmedCode, getOrCreateLicenseDeviceId());
        writeCachedLicenseToken(token);
        if (token.status === 'INACTIVE') {
            clearCachedLicenseToken();
            return buildInactiveResult('Activation was not valid.');
        }
        return {
            status: token.status,
            isActive: true,
            reason: buildActiveReason(token.status),
            token,
        };
    }
    catch (error) {
        if (error instanceof LicenseEndpointError) {
            return buildInactiveResult(error.message);
        }
        return buildInactiveResult('License activation failed. Please try again.');
    }
};
export const validateCachedLicense = async () => {
    const token = readCachedLicenseToken();
    const now = new Date();
    if (!token) {
        return buildInactiveResult('No license is activated.');
    }
    if (token.status === 'INACTIVE') {
        clearCachedLicenseToken();
        return buildInactiveResult('License is inactive.');
    }
    if (isTokenActive(token, now) && !shouldRefreshToken(token, now)) {
        return {
            status: token.status,
            isActive: true,
            reason: buildActiveReason(token.status),
            token,
        };
    }
    const endpoint = getEndpoint();
    if (!endpoint) {
        if (isWithinGraceWindow(token, now)) {
            return {
                status: token.status,
                isActive: true,
                reason: 'License service is unavailable. Running inside offline grace window.',
                token,
            };
        }
        clearCachedLicenseToken();
        return buildInactiveResult('License service is not configured.');
    }
    try {
        const refreshed = await requestRefreshFromEndpoint(endpoint, token, getOrCreateLicenseDeviceId());
        if (refreshed.status === 'INACTIVE') {
            clearCachedLicenseToken();
            return buildInactiveResult('License is inactive.');
        }
        writeCachedLicenseToken(refreshed);
        return {
            status: refreshed.status,
            isActive: true,
            reason: buildActiveReason(refreshed.status, true),
            token: refreshed,
        };
    }
    catch (error) {
        if (error instanceof LicenseEndpointError) {
            if (error.isUnavailable && isWithinGraceWindow(token, now)) {
                return {
                    status: token.status,
                    isActive: true,
                    reason: 'License service unavailable. Running inside offline grace window.',
                    token,
                };
            }
            clearCachedLicenseToken();
            return buildInactiveResult(error.message);
        }
        if (isWithinGraceWindow(token, now)) {
            return {
                status: token.status,
                isActive: true,
                reason: 'License service unavailable. Running inside offline grace window.',
                token,
            };
        }
        clearCachedLicenseToken();
        return buildInactiveResult('License expired and grace window ended.');
    }
};
export const clearLicense = () => {
    clearCachedLicenseToken();
};
