const DEFAULT_LICENSE_API_BASE_URL = 'https://gbewxqwduetspfdfzsgx.supabase.co/functions/v1';
const DEFAULT_SUPPORT_EMAIL = 'support@reclude.io';
const normalizeChannel = (value) => {
    if (value === 'stable' || value === 'preview' || value === 'development') {
        return value;
    }
    return 'unknown';
};
const resolveFeedUrl = (url, isDevelopmentBuild) => {
    if (isDevelopmentBuild) {
        return null;
    }
    return new URL('update-feed.json', url).toString();
};
const readSearchParam = (url, key) => url.searchParams.get(key)?.trim() || '';
export const getInstalledVersionInfo = () => {
    const currentUrl = new URL(window.location.href);
    const isDevelopmentBuild = currentUrl.hostname === 'localhost';
    const channel = normalizeChannel(currentUrl.searchParams.get('channel'));
    const manifestVersion = readSearchParam(currentUrl, 'manifestVersion') || __APP_VERSION__;
    const installerVersion = readSearchParam(currentUrl, 'installerVersion') || manifestVersion;
    const licenseApiBaseUrl = readSearchParam(currentUrl, 'licenseApiBaseUrl') || DEFAULT_LICENSE_API_BASE_URL;
    const supportEmail = readSearchParam(currentUrl, 'supportEmail') || DEFAULT_SUPPORT_EMAIL;
    return {
        appVersion: __APP_VERSION__,
        manifestVersion,
        installerVersion,
        channel: isDevelopmentBuild ? 'development' : channel,
        isDevelopmentBuild,
        feedUrl: resolveFeedUrl(currentUrl, isDevelopmentBuild),
        licenseApiBaseUrl,
        supportEmail,
    };
};
